window.RP_SESSION={"id":"S-55694cbd710d","messages":[{"id":"RP-III-0136627","time":"2026-08-08T04:26:00+09:00","room":"RP III","name":"세드릭","profile":"세드릭","identity":"reviewed","type":"dialogue","body":"[아이야, 너의 꿈을 끝까지 놓지 말아라. 어디로 나아가야 할지 알 수 없을 때, 그 별은 너의 유일한 안내자가 될테니. 잃어버린 너 스스로를 저버러지 말렴. 나는 여기에서, 너를 지켜보마. 나의 이름은,]","characters":["P-4b8d7bf3c420"]},{"id":"RP-III-0136628","time":"2026-08-08T04:26:00+09:00","room":"RP III","name":"세드릭","profile":"세드릭","identity":"reviewed","type":"dialogue","body":"“흐어헉 컥…”","characters":["P-4b8d7bf3c420"]},{"id":"RP-III-0136629","time":"2026-08-08T04:27:00+09:00","room":"RP III","name":"세드릭","profile":"세드릭","identity":"reviewed","type":"dialogue","body":"“… 뭐지.”","characters":["P-4b8d7bf3c420"]},{"id":"RP-III-0136630","time":"2026-08-08T04:28:00+09:00","room":"RP III","name":"세드릭","profile":"세드릭","identity":"reviewed","type":"dialogue","body":"개꿈이라 치부하기에는, 분명히 뭔가가 느껴졌다. 마치 먼 곳, 아니. 멀다기에는 오히려 가까운, 가깝고도 너무나 가까워 그 거리를 느낄 수 없는.","characters":["P-4b8d7bf3c420"]},{"id":"RP-III-0136631","time":"2026-08-08T04:28:00+09:00","room":"RP III","name":"세드릭","profile":"세드릭","identity":"reviewed","type":"dialogue","body":"“… 진짜 뭐지.”","characters":["P-4b8d7bf3c420"]},{"id":"RP-III-0136632","time":"2026-08-08T04:30:00+09:00","room":"RP III","name":"세드릭","profile":"세드릭","identity":"reviewed","type":"dialogue","body":"요 근래 그러한 생각을 간간히 하고는 한다. 뭔가… 손에 쥐고 있던 게 당연했던 것을 잃어버린 느낌.","characters":["P-4b8d7bf3c420"]},{"id":"RP-III-0136633","time":"2026-08-08T04:31:00+09:00","room":"RP III","name":"세드릭","profile":"세드릭","identity":"reviewed","type":"dialogue","body":"“… 순돌이인가. 아닌데. 잘 가져다 놨는데.”","characters":["P-4b8d7bf3c420"]},{"id":"RP-III-0136634","time":"2026-08-08T04:32:00+09:00","room":"RP III","name":"세드릭","profile":"세드릭","identity":"reviewed","type":"dialogue","body":"한숨을 내쉬며 다시 눕는다.","characters":["P-4b8d7bf3c420"]},{"id":"RP-III-0136635","time":"2026-08-08T04:36:00+09:00","room":"RP III","name":"세드릭","profile":"세드릭","identity":"reviewed","type":"dialogue","body":"내일이 오면… 또 잊어버리겠지.","characters":["P-4b8d7bf3c420"]},{"id":"RP-III-0136636","time":"2026-08-08T04:36:00+09:00","room":"RP III","name":"세드릭","profile":"세드릭","identity":"reviewed","type":"dialogue","body":"그리고 또 다른 여정이 있겠지.","characters":["P-4b8d7bf3c420"]},{"id":"RP-III-0136637","time":"2026-08-08T04:38:00+09:00","room":"RP III","name":"세드릭","profile":"세드릭","identity":"reviewed","type":"dialogue","body":"그 반복되는 나날 속에서, 나는 어쩌면, 무언가를 향해 쓸려가는 중일지도.","characters":["P-4b8d7bf3c420"]},{"id":"RP-III-0136638","time":"2026-08-08T04:38:00+09:00","room":"RP III","name":"세드릭","profile":"세드릭","identity":"reviewed","type":"dialogue","body":"“커어커커커걹…”","characters":["P-4b8d7bf3c420"]},{"id":"RP-III-0136639","time":"2026-08-08T04:39:00+09:00","room":"RP III","name":"세드릭","profile":"세드릭","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-4b8d7bf3c420"]},{"id":"RP-III-0136640","time":"2026-08-08T04:39:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"...good for you.","characters":[]}]};
